"""SQLite declarations. Importing this module never opens or changes a database."""
from sqlalchemy import MetaData, Table, Column, String, Integer, LargeBinary, Float, ForeignKey, UniqueConstraint, CheckConstraint

metadata = MetaData()
users = Table("users", metadata, Column("id", String, primary_key=True), Column("username", String, unique=True, nullable=False), Column("password_hash", String, nullable=False), Column("role", String, nullable=False), CheckConstraint("role IN ('admin','member')", name="valid_role"))
files = Table("files", metadata, Column("id", String, primary_key=True), Column("owner_id", String, ForeignKey("users.id"), nullable=False), Column("name", String, nullable=False), Column("content", LargeBinary, nullable=False), Column("state", String, nullable=False), Column("reason", String, nullable=False), Column("revision", Integer, nullable=False), Column("created_at", Float, nullable=False), CheckConstraint("state IN ('pending','approved','rejected')", name="valid_file_state"))
shares = Table("shares", metadata, Column("id", String, primary_key=True), Column("file_id", String, ForeignKey("files.id"), nullable=False), Column("recipient_id", String, ForeignKey("users.id"), nullable=False), UniqueConstraint("file_id", "recipient_id", name="unique_recipient"))
jobs = Table("jobs", metadata, Column("id", String, primary_key=True), Column("file_id", String, ForeignKey("files.id"), nullable=False), Column("recipient_id", String, ForeignKey("users.id"), nullable=False), Column("kind", String, nullable=False), Column("text", String, nullable=False), Column("carrier", String, nullable=False), Column("due_at", Float, nullable=False), Column("state", String, nullable=False), CheckConstraint("state IN ('queued','delivered')", name="valid_job_state"))
messages = Table("messages", metadata, Column("id", String, primary_key=True), Column("job_id", String, ForeignKey("jobs.id"), unique=True, nullable=False), Column("recipient_id", String, ForeignKey("users.id"), nullable=False), Column("file_id", String, ForeignKey("files.id"), nullable=False), Column("kind", String, nullable=False), Column("text", String, nullable=False), Column("created_at", Float, nullable=False))
journal = Table("journal", metadata, Column("id", String, primary_key=True), Column("file_id", String, ForeignKey("files.id"), nullable=False), Column("event", String, nullable=False), Column("before_state", String, nullable=False), Column("after_state", String, nullable=False), Column("actor_id", String, ForeignKey("users.id"), nullable=False), Column("revision", Integer, nullable=False), Column("guards", String, nullable=False))
